use atlas_faiss_probe::Index;
#[test] fn reconstruct_roundtrip_and_invalid_id(){let mut idx=Index::new().unwrap();let mut a=[0f32;512];for(i,x)in a.iter_mut().enumerate(){*x=(i as f32-255.)/512.;}let mut b=[0f32;512];b[0]=0.6;b[1]=0.8;idx.add(&[a,b]).unwrap();assert_eq!(idx.reconstruct(0).unwrap(),a);assert_eq!(idx.reconstruct(1).unwrap(),b);assert!(idx.reconstruct(-1).is_err());assert!(idx.reconstruct(2).is_err());let p=std::env::temp_dir().join(format!("atlas-reconstruct-{}",std::process::id()));idx.save(&p).unwrap();let restored=Index::load(&p).unwrap();assert_eq!(restored.reconstruct(1).unwrap(),b);std::fs::remove_file(p).unwrap();}
